-- ============================================================================
-- DailyLift — seed the shared exercise library (38 global exercises).
-- Idempotent: keyed on the unique slug, ON CONFLICT DO NOTHING. Safe to re-run
-- and safe on a fresh database. created_by is NULL => these are global rows
-- visible to everyone via the existing "view global or own exercises" policy.
-- Does not touch or overwrite user-created custom exercises.
-- ============================================================================

ON CONFLICT (slug) DO NOTHING;

NOTIFY pgrst, 'reload schema';
